def rr(x0,y0,x1,y1,r):
    r=min(r,(x1-x0)/2,(y1-y0)/2);f=lambda v:('%g'%v)
    return 'M%s %sH%sQ%s %s %s %sV%sQ%s %s %s %sH%sQ%s %s %s %sV%sQ%s %s %s %sZ'%tuple(map(f,(x0+r,y0,x1-r,x1,y0,x1,y0+r,y1-r,x1,y1,x1-r,y1,x0+r,x0,y1,x0,y1-r,y0+r,x0,y0,x0+r,y0)))
def svg(lst):
    o=''
    for j,p in enumerate(lst):
        fill=Y if p[1]=='Y' else C if p[1]=='C' else None
        if p[0]=='p': d='M'+'L'.join('%g %g'%tuple(q) for q in p[2])+'Z'
        elif p[0]=='l': d='M'+'L'.join('%g %g'%tuple(q) for q in p[2])
        elif p[0]=='r': d=rr(*p[2:7])
        else: d='M%g %ga%g %g 0 1 0 %g 0a%g %g 0 1 0 %g 0'%(p[2]-p[4],p[3],p[4],p[4],2*p[4],p[4],p[4],-2*p[4])
        dl='--j:%d'%j
        if fill: o+='<path class="fl" d="%s" fill="%s" style="%s"/>'%(d,fill,dl)
        o+='<path class="ln" pathLength="1" d="%s" style="%s"/>'%(d,dl)
    return '<svg class="mr-cat" viewBox="-195 -120 390 200" aria-hidden="true">'+o+'</svg>'
